<?php require __DIR__.'/../bootstrap.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: dashboard.php');exit;}check_csrf();$id=(int)($_POST['id']??0);$st=db()->prepare('SELECT attachment FROM bug_reports WHERE id=?');$st->execute([$id]);$r=$st->fetch();if($r){db()->prepare('DELETE FROM bug_reports WHERE id=?')->execute([$id]);if($r['attachment']&&is_file(__DIR__.'/../'.$r['attachment']))@unlink(__DIR__.'/../'.$r['attachment']);}flash('Report deleted.');header('Location: dashboard.php');
